E(6, "O objeto é o que é transformado. O verbo é o que transforma.", "O objeto é o que é transformado, e o verbo é o que transforma.")
E(6, "como na fita: os quadros de um lado,", "como na fita, os quadros de um lado,")
E(6, "Não é o primeiro quadro nem o último. É o que está entre eles. Deus não é o começo nem o fim: é o meio.",
     "Em vez do primeiro ou do último quadro, Deus é o que está entre eles, o meio, e não o começo ou o fim.")
E(6, "há um verbo: abrir.", "há um verbo, abrir.")
E(6, "se desdobra em verbos menores: pegar a chave,", "se desdobra em verbos menores, como pegar a chave,")
E(6, "E cada um pode se desdobrar de novo: girar a chave", "E cada um pode se desdobrar de novo, e girar a chave")
